<?php
require_once __DIR__ . '/_api.php';
if($_SERVER['REQUEST_METHOD']!=='POST') marketplace_api_json(['success'=>false,'message'=>'Method tidak diizinkan.'],405);
try{marketplace_api_throttle('wishlist',150);$payload=marketplace_api_payload();marketplace_api_require_csrf($payload);$db=Database::connect();marketplace_install($db);$cid=marketplace_customer_id();if($cid<=0||!marketplace_customer($db))marketplace_api_json(['success'=>false,'message'=>'Silakan masuk ke akun marketplace terlebih dahulu.','login_url'=>legacy_base_url('masuk')],401);$pid=(int)($payload['product_id']??0);$p=$db->prepare("SELECT id FROM products WHERE id=? AND is_active=1 LIMIT 1");$p->execute([$pid]);if(!(int)$p->fetchColumn())throw new InvalidArgumentException('Produk tidak ditemukan.');$c=$db->prepare("SELECT id FROM marketplace_wishlists WHERE customer_id=? AND product_id=? LIMIT 1");$c->execute([$cid,$pid]);$wid=(int)$c->fetchColumn();if($wid){$db->prepare("DELETE FROM marketplace_wishlists WHERE id=?")->execute([$wid]);$active=false;}else{$db->prepare("INSERT IGNORE INTO marketplace_wishlists(customer_id,product_id,created_at) VALUES(?,?,NOW())")->execute([$cid,$pid]);$active=true;}marketplace_api_json(['success'=>true,'active'=>$active,'message'=>$active?'Ditambahkan ke wishlist.':'Dihapus dari wishlist.']);}catch(Throwable $e){marketplace_api_error($e);}
